package com.mycompany.rentalmanagement.servlet;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;@WebServlet("/logout") public class LogoutServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws IOException{HttpSession h=r.getSession(false);if(h!=null)h.invalidate();s.sendRedirect(r.getContextPath()+"/login?loggedout=1");}}
